{
  "_comment": "REFERENCE MANIFEST, NOT AN API PAYLOAD. The Insider Risk Indicators (preview) connector, custom indicator creation, and Insider Risk Management policy authoring are all portal-only workflows with no documented Graph/PowerShell write API (design.md §4). No script in this scenario's deploy/ folder reads or applies this file - it is a structured, versioned source of truth for the person completing the portal steps in README.md §5, recording the connector's CSV mapping, the custom indicator(s) created from it, and the policy trigger/scoring configuration, since none of this can be read back via any API.",
  "connector": {
    "type": "Insider Risk Indicators (preview)",
    "name": "OPERATOR CHOICE - e.g. 'Third-Party CASB/DLP Detections'",
    "entraAppId": "OPERATOR VALUE - the Application (client) ID from ../../departing-employee-data-theft/deploy/Register-HrConnectorApp.ps1 -DisplayName '<this connector's app>' (reused unmodified, README.md §5 Step 2)",
    "jobId": "OPERATOR VALUE - generated by the Purview portal when the connector is created (README.md §5 Step 3); required by deploy/Send-InsiderRiskIndicatorRecord.ps1 -JobId",
    "sampleFile": {
      "worked example": "Microsoft's own documented multi-indicator example (import-insider-risk-indicators, Example 2): one CSV covering Salesforce and Dropbox aggregated alerts, routed via a Source column - design.md §6.",
      "columns": {
        "UserColumn": "User_Principal_Name (OPERATOR CHOICE of column name - Microsoft does not fix it; matches deploy/Send-InsiderRiskIndicatorRecord.ps1 -UserColumn)",
        "EventTimeColumn": "Aggregation_Date, ISO 8601 (yyyy-mm-ddThh:mm:ss.nnnnnn+|-hh:mm) - mandatory role, any column name",
        "ThresholdColumn": "Alert_Count - OPTIONAL, must be mapped as a Number data type in the portal's 'Verify sample data and data type' step if a custom indicator built from this connector will use a threshold",
        "SourceColumn": "Source_Workload - OPTIONAL, required only for the multi-indicator-from-one-CSV pattern"
      },
      "sourceColumnConfig": {
        "selected": "OPERATOR CHOICE - 'None (Single source)' or the actual source column name",
        "relatedValuesInSourceColumn": "OPERATOR VALUE, comma-separated, NO spaces - e.g. 'Salesforce,Dropbox'. MUST match deploy/Send-InsiderRiskIndicatorRecord.ps1 -RelatedValues exactly and the actual values present in the CSV's source column - Microsoft: 'The connector fails if the column values don't match.'"
      }
    },
    "dataMapping": {
      "eventTimeUtc": "Maps to EventTimeColumn above - mandatory field in the portal's Data mapping page",
      "userEmailAddress": "Maps to UserColumn above - mandatory field in the portal's Data mapping page",
      "additionalFieldsSelected": "OPERATOR CHOICE - any other CSV columns to surface as supporting context in Activity explorer/alerts/cases (not used for triggering or scoring)"
    },
    "firewallAllowlist": "webhook.ingestion.office.com MUST be allowlisted wherever deploy/Send-InsiderRiskIndicatorRecord.ps1 runs from, or the upload silently fails to reach the service."
  },
  "customIndicators": [
    {
      "name": "OPERATOR CHOICE - e.g. 'Salesforce - Sensitive Report Exfiltration (third-party)'",
      "sourceColumnValue": "Salesforce - must match one of connector.sampleFile.sourceColumnConfig.relatedValuesInSourceColumn",
      "thresholdField": "OPERATOR CHOICE - the mapped ThresholdColumn (e.g. Alert_Count), OR 'Use only as a triggering event without any thresholds' (mutually exclusive - selecting the no-threshold option means this indicator CANNOT be given a trigger threshold later, README.md §11)",
      "usedAsTrigger": "OPERATOR CHOICE - true/false, set on the policy's Triggers page, not here",
      "usedAsScoringIndicator": "OPERATOR CHOICE - true/false, set on the policy's Indicators page, not here"
    },
    {
      "name": "OPERATOR CHOICE - e.g. 'Dropbox - Anomalous Personal-Cloud Copy (third-party)'",
      "sourceColumnValue": "Dropbox - must match one of connector.sampleFile.sourceColumnConfig.relatedValuesInSourceColumn",
      "thresholdField": "OPERATOR CHOICE, same rules as above",
      "usedAsTrigger": "OPERATOR CHOICE",
      "usedAsScoringIndicator": "OPERATOR CHOICE"
    }
  ],
  "policy": {
    "policyName": "Data Leaks - Custom Indicator (Third-Party Connector) Trigger",
    "policyTemplate": "Data leaks",
    "templateScopeCaveat": "Microsoft's own wording for which templates support custom indicators ('any Data theft or Data leaks policies') is not precise enough to confirm this extends beyond the base Data leaks template - design.md §2 goal 7/README.md §11. This manifest and scenario are scoped to the base Data leaks template only.",
    "scope": {
      "users": "A plain Entra security group (or groups), resolved via ../../security-policy-violations/deploy/Get-SecurityPolicyViolationsScopeCandidates.ps1 (reused unmodified) - identical population mechanism to both sibling Data-leaks-template scenarios in this library.",
      "maxUsersInScope": 15000,
      "note": "PER-TEMPLATE cap, shared cumulatively with BOTH sibling scenarios (scenarios/insider-risk/data-leaks/ and scenarios/insider-risk/data-leaks-exfiltration-activity-trigger/) if all three are deployed in the same tenant - now a three-way shared pool, not just two."
    },
    "triggeringEvent": {
      "type": "Custom indicator (from the Insider Risk Indicators connector)",
      "alternativesNotUsedHere": [
        "User matches a data loss prevention (DLP) policy - see scenarios/insider-risk/data-leaks/",
        "User performs an exfiltration activity (built-in indicators) - see scenarios/insider-risk/data-leaks-exfiltration-activity-trigger/"
      ],
      "selectedCustomIndicators": "OPERATOR CHOICE - list which of customIndicators[] above are selected on the policy's Triggers page",
      "thresholdMode": "MUST be a custom threshold - Microsoft: 'Insider Risk Management doesn't provide recommended thresholds for custom indicators.' There is no default-threshold option to select for a custom indicator used as a trigger.",
      "customThresholdValue": "OPERATOR CHOICE - record the actual threshold value(s) entered in the portal here, since there is no read API"
    },
    "scoringIndicators": {
      "_note": "A SEPARATE decision from triggeringEvent.selectedCustomIndicators above, same two-independent-decisions model the exfiltration-activity-trigger sibling's manifest already documents for built-in indicators.",
      "officeIndicators": {
        "selected": true,
        "note": "Primary built-in scoring category for this template - identical to both siblings."
      },
      "cumulativeExfiltrationDetection": {
        "selected": true,
        "note": "Enabled by default for this template - confirm actually selected at policy creation."
      },
      "customIndicatorsAlsoUsedForScoring": "OPERATOR CHOICE - list which of customIndicators[] above (if any) are ALSO selected on the policy's Indicators page, with their own independently-configured custom threshold"
    }
  },
  "syncWaitRequirement": "Wait 24 hours after creating/updating the custom indicator(s) and this policy before running deploy/Send-InsiderRiskIndicatorRecord.ps1 for the first time (or after any indicator/policy change) - Microsoft: 'It can take several hours to sync all components. If you immediately upload the data while the updates are syncing, some data might not be scored for risk.'",
  "alertReview": {
    "pseudonymizeUserNames": true,
    "note": "Repo default - do not disable pseudonymization without an explicit, documented privacy/legal decision. Same as every IRM scenario in this library."
  },
  "schemaVersion": "1.0",
  "lastUpdated": "2026-09-16"
}
